/// Adds every generated collection to a loading state:
/// `LoadingState::new(S::Loading).continue_to_state(S::Ready).with(load_all_collections)`
/// or `load_all_collections(LoadingState::new(..))`.
pub fn load_all_collections<T: ConfigureLoadingState>(state: T) -> T {
    state
        .load_collection::<CharacterAssets>()
        .load_collection::<CharacterAnimations>()
        .load_collection::<MechAssets>()
        .load_collection::<MechAnimations>()
        .load_collection::<VehicleAssets>()
        .load_collection::<WeaponAssets>()
        .load_collection::<PropAssets>()
        .load_collection::<PropAnimations>()
        .load_collection::<EnvironmentAssets>()
        .load_collection::<ModularAssets>()
        .load_collection::<ModularAnimations>()
        .load_collection::<ShipAssets>()
}

/// Every model scene in every loaded collection, as `(category, field name, handle)`.
/// Collections that are not inserted yet are skipped.
pub fn all_scenes(world: &World) -> Vec<(&'static str, &'static str, Handle<WorldAsset>)> {
    let mut out = Vec::new();
    if let Some(c) = world.get_resource::<CharacterAssets>() {
        out.extend(c.all().into_iter().map(|(n, h)| ("characters", n, h.clone())));
    }
    if let Some(c) = world.get_resource::<MechAssets>() {
        out.extend(c.all().into_iter().map(|(n, h)| ("mechs", n, h.clone())));
    }
    if let Some(c) = world.get_resource::<VehicleAssets>() {
        out.extend(c.all().into_iter().map(|(n, h)| ("vehicles", n, h.clone())));
    }
    if let Some(c) = world.get_resource::<WeaponAssets>() {
        out.extend(c.all().into_iter().map(|(n, h)| ("weapons", n, h.clone())));
    }
    if let Some(c) = world.get_resource::<PropAssets>() {
        out.extend(c.all().into_iter().map(|(n, h)| ("props", n, h.clone())));
    }
    if let Some(c) = world.get_resource::<EnvironmentAssets>() {
        out.extend(c.all().into_iter().map(|(n, h)| ("environment", n, h.clone())));
    }
    if let Some(c) = world.get_resource::<ModularAssets>() {
        out.extend(c.all().into_iter().map(|(n, h)| ("modular", n, h.clone())));
    }
    if let Some(c) = world.get_resource::<ShipAssets>() {
        out.extend(c.all().into_iter().map(|(n, h)| ("ships", n, h.clone())));
    }
    out
}

